import{_ as e}from"./chunks/attachments-overview.Cbfmfi6R.js";import{_ as a,o as d,c as r,a5 as o}from"./chunks/framework.DbSlGjul.js";const b=JSON.parse('{"title":"Module reference","description":"","frontmatter":{},"headers":[],"relativePath":"hardware/modules.md","filePath":"hardware/modules.md","lastUpdated":1789045003000}'),s={name:"hardware/modules.md"};function l(i,t,h,n,c,u){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="module-reference" tabindex="-1">Module reference <a class="header-anchor" href="#module-reference" aria-label="Permalink to &quot;Module reference&quot;">​</a></h1><p>HiveBoard contains 13 scored attachment configurations across three task families. The ball valve is evaluated both without and with a friction ring, producing two separate trial sets.</p><p>For operating instructions, use <a href="/hivedocs/benchmark/tasks">How to perform each task</a>. It includes the starting state and reset for each mechanism, with a <a href="/hivedocs/benchmark/tasks#shock-absorber">step-by-step shock absorber task</a>.</p><figure class="doc-image"><img src="'+e+'" alt="Overview of the thirteen HiveBoard attachment configurations"><figcaption>Attachment overview. Each mechanism uses the shared honeycomb mounting interface.</figcaption></figure><h2 id="torque-tasks" tabindex="-1">Torque tasks <a class="header-anchor" href="#torque-tasks" aria-label="Permalink to &quot;Torque tasks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Attachment</th><th>Required outcome</th><th style="text-align:right;">Timeout</th></tr></thead><tbody><tr><td><code>valve_ball</code></td><td>Ball valve</td><td>Rotate the handle 90° from closed to open</td><td style="text-align:right;">60 s</td></tr><tr><td><code>valve_ball_ring</code></td><td>Ball valve with friction ring</td><td>Rotate the handle 90° with the ring fitted</td><td style="text-align:right;">90 s</td></tr><tr><td><code>valve_gate_small</code></td><td>Small gate valve</td><td>Complete one full turn of the stem</td><td style="text-align:right;">90 s</td></tr><tr><td><code>valve_gate_large</code></td><td>Large gate valve</td><td>Complete one full turn of the stem</td><td style="text-align:right;">120 s</td></tr><tr><td><code>circuit_breaker</code></td><td>Circuit breaker</td><td>Move the toggle to the other state and hold it</td><td style="text-align:right;">60 s</td></tr></tbody></table><p>The gate-valve criterion is one complete stem rotation, not full travel. The number of turns required for full travel can vary with the printed thread pitch.</p><h2 id="precision-tasks" tabindex="-1">Precision tasks <a class="header-anchor" href="#precision-tasks" aria-label="Permalink to &quot;Precision tasks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Attachment</th><th>Required outcome</th><th style="text-align:right;">Timeout</th></tr></thead><tbody><tr><td><code>light_bulb</code></td><td>Light bulb and socket</td><td>Thread the bulb until it is seated</td><td style="text-align:right;">120 s</td></tr><tr><td><code>thread_m8</code></td><td>M8 threaded fastener</td><td>Thread the bolt along the available length</td><td style="text-align:right;">120 s</td></tr><tr><td><code>thread_m30</code></td><td>M30 threaded fastener</td><td>Thread the bolt along the available length</td><td style="text-align:right;">120 s</td></tr><tr><td><code>peg_insertion</code></td><td>Threaded peg insertion</td><td>Thread the free peg into the empty socket until seated</td><td style="text-align:right;">120 s</td></tr></tbody></table><p>The peg task uses a threaded 8 mm pin. It is not a clearance-fit insertion task.</p><h2 id="composed-assembly-tasks" tabindex="-1">Composed assembly tasks <a class="header-anchor" href="#composed-assembly-tasks" aria-label="Permalink to &quot;Composed assembly tasks&quot;">​</a></h2><p>These tasks are scored by the last completed stage as well as by full success.</p><table tabindex="0"><thead><tr><th>ID</th><th>Attachment</th><th>Stage 1</th><th>Stage 2</th><th>Stage 3</th><th style="text-align:right;">Timeout</th></tr></thead><tbody><tr><td><code>button</code></td><td>Covered button</td><td>Open cover</td><td>Press button</td><td>—</td><td style="text-align:right;">60 s</td></tr><tr><td><code>lock</code></td><td>Lock and key</td><td>Grasp key</td><td>Insert key vertically</td><td>Rotate to unlock</td><td style="text-align:right;">180 s</td></tr><tr><td><code>drawer</code></td><td>Sliding drawer</td><td>Grasp handle</td><td>Pull open</td><td>Push closed</td><td style="text-align:right;">120 s</td></tr><tr><td><code>shock_absorber</code></td><td>Shock absorber</td><td>Grasp pin</td><td>Align with hole</td><td>Insert fully</td><td style="text-align:right;">180 s</td></tr></tbody></table><p>Record <code>0</code> when no stage is completed. A full success reaches the final stage listed for the attachment.</p><h2 id="printable-files" tabindex="-1">Printable files <a class="header-anchor" href="#printable-files" aria-label="Permalink to &quot;Printable files&quot;">​</a></h2><p>The module folders and their components are available under <a href="https://github.com/EESC-LabRoM/HiveBoard/tree/main/STL" target="_blank" rel="noreferrer"><code>STL/</code></a>. The same high-level folder names are used under <code>CAD/</code> and <code>Simulation/</code> where the corresponding assets are available.</p>',16)])])}const p=a(s,[["render",l]]);export{b as __pageData,p as default};
